class Ball {
  late Object ball;
  double radius = 6.5;
  double velocityX = 0;
  double velocityY = 0;
  double CUSHION_RESTITUTION = 0.8;
  bool apply = false;

  Ball(String fileName, double initialX, double initialY) {
    ball = Object(
      fileName: fileName,
    );

    // Define a rotação inicial da bola
    ball.rotation.setValues(-180, -90, -59);
    ball.position.setValues(initialX, initialY, 0);

    ball.scale.setValues(radius, radius, radius);
  }

  Object get object => ball;

  double angularVelocity = 0.0;

  double angle = 0; // Inicializa o ângulo

  double rotationSpeed = 10;

  void update(double dt, double friction, List<Rectangle> rectangles) {
    ball.position.x += velocityX * dt;
    ball.position.y += velocityY * dt;

    velocityX *= friction;
    velocityY *= friction;
    // Suponha que você tenha uma força e um ângulo
    double force = 5.0; // Força aplicada
    double rotationSpeed = 1.0; // Velocidade de rotação
    double deltaTime = 0.016; // Tempo decorrido (por exemplo, 16ms para 60fps)

    // Calcular o ângulo de rotação em radianos
    double rotationAmount = force * rotationSpeed * deltaTime;

    // Determinar o eixo de rotação (por exemplo, em torno do eixo Y)
    Vector3 rotationAxis = Vector3(1, 0, 1);

    // Criar o quaternion de rotação
    Quaternion deltaRotation =
        Quaternion.axisAngle(rotationAxis, rotationAmount);

    // Suponha que você tenha uma bola com uma orientação inicial
    Quaternion currentOrientation = Quaternion.identity();

    // Aplicar a rotação à orientação atual da bola
    Quaternion newOrientation = currentOrientation * deltaRotation;

    ball.rotation.applyQuaternion(newOrientation);

    for (var rect in rectangles) {
      // Verificar colisão com o retângulo
      if (ball.position.x + radius > rect.x &&
          ball.position.x - radius < rect.x + rect.width &&
          ball.position.y + radius > rect.y &&
          ball.position.y - radius < rect.y + rect.height) {
        // Calcular o ponto mais próximo no retângulo
        double nearestX =
            max(rect.x, min(ball.position.x, rect.x + rect.width));
        double nearestY =
            max(rect.y, min(ball.position.y, rect.y + rect.height));

        // Calcular a distância do ponto mais próximo até o centro da bola
        double deltaX = ball.position.x - nearestX;
        double deltaY = ball.position.y - nearestY;
        double distance = sqrt(deltaX * deltaX + deltaY * deltaY);

        if (distance < radius) {
